from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel
from .nonprofit_cause import NonprofitCause, NonprofitCauseDict


class Nonprofit(SdkBaseModel):
    causes: list[NonprofitCause]
    """The causes that the nonprofit supports."""

    description: str
    """The description of the nonprofit."""

    goals: list[str]
    """The goals of the nonprofit."""

    id: Optional[str] = UNSET
    """The unique identifier of the nonprofit organization. This value is generated by Adyen."""

    locales: list[str]
    """The locales that the nonprofit supports, in `IETF BCP 47 <https://en.wikipedia.org/wiki/IETF_language_tag>`__
    format."""

    logo_url: str = Field(alias="logoUrl")
    """The URL to the logo of the nonprofit."""

    name: str
    """The name of the nonprofit."""

    regions: list[str]
    """The regions where the nonprofit operates, in `ISO 3166-1 alpha-2
    <https://en.wikipedia.org/wiki/ISO_3166-1_alpha-2>`__ format."""

    terms_and_conditions_url: str = Field(alias="termsAndConditionsUrl")
    """The URL to the terms and conditions of the nonprofit."""

    website: str
    """The URL to the website of the nonprofit."""


class NonprofitDict(TypedDict):
    causes: list[NonprofitCauseDict]
    description: str
    goals: list[str]
    id: NotRequired[str]
    locales: list[str]
    logo_url: str
    name: str
    regions: list[str]
    terms_and_conditions_url: str
    website: str
